package br.com.onda;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;
public class MemoryTextTest {
 @Test public void questionsBecomeSafeAccentInsensitivePrefixWords(){assertEquals("explicacao* juros*",MemoryText.query("Ache a parte do vídeo com explicação sobre juros"));assertEquals("",MemoryText.query("ache o trecho do vídeo"));assertFalse(MemoryText.query("juros' OR 1=1; DROP TABLE words--").contains("'"));assertTrue(MemoryText.query("ação emoção").contains("acao"));}
 @Test public void srtKeepsExactTimesAndStripsHtmlAndSequenceNumbers(){List<MemoryText.Cue> cues=MemoryText.subtitles("1\r\n00:00:01,200 --> 00:00:03,450\r\n<b>Trocar pneu</b>\r\n\r\n2\r\n00:00:04,000 --> 00:00:05,000\r\nConferir pressão\r\n");assertEquals(2,cues.size());assertEquals(1200,cues.get(0).start);assertEquals(3450,cues.get(0).end);assertEquals("Trocar pneu",cues.get(0).text);assertFalse(cues.get(1).text.contains("2"));}
 @Test public void webvttAcceptsMinuteTimesAndRejectsInvalidClock(){List<MemoryText.Cue> cues=MemoryText.subtitles("WEBVTT\n\n00:01.000 --> 00:03.000 align:start\nTexto brasileiro\n\n00:70.000 --> 00:72.000\nNão aceitar\n");assertEquals(1,cues.size());assertEquals(1000,cues.get(0).start);assertEquals(3000,cues.get(0).end);}
 @Test public void chunksAreBoundedAndDoNotDropText(){String text=String.join(" ",Collections.nCopies(1500,"pneumático"));List<String> chunks=MemoryText.chunks(text);assertTrue(chunks.size()>1);assertEquals(text,String.join(" ",chunks));for(String c:chunks)assertTrue(c.length()<=1200);}
 @Test public void spokenNumbersAreNotDiscardedAsSequenceCounters(){List<MemoryText.Cue> cues=MemoryText.subtitles("1\n00:00:01,000 --> 00:00:02,000\n123456\n");assertEquals(1,cues.size());assertEquals("123456",cues.get(0).text);}
 @Test public void invertedOrUnmarkedTranscriptNeverInventsOffsets(){assertTrue(MemoryText.subtitles("Uma transcrição sem horários").isEmpty());assertTrue(MemoryText.subtitles("00:00:04,000 --> 00:00:02,000\nErrado").isEmpty());}
}
